describe('Inline PDF Viewer - File Upload', () => {
  beforeEach(() => {
    cy.visit('/file-upload');
  });

  it('should display uploaded PDF in inline viewer', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/files/upload').as('uploadFile');

    // Get the file input element
    cy.get('[data-testid="pdf-file-input"]').selectFile('cypress/fixtures/sample.pdf', { force: true });

    // Verify file name is displayed
    cy.get('[data-testid="uploaded-file-name"]').should('contain', 'sample.pdf');

    // Click upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for API call
    cy.wait('@uploadFile');

    // Verify success message
    cy.get('[data-testid="success-message"]').should('be.visible').should('contain', 'File uploaded successfully');

    // Verify inline viewer is visible
    cy.get('[data-testid="pdf-viewer-container"]').should('be.visible');

    // Verify PDF viewer has content
    cy.get('[data-testid="pdf-viewer-canvas"]').should('be.visible');

    // Verify viewer displays first page
    cy.get('[data-testid="pdf-page-number"]').should('contain', '1');
  });

  it('should handle invalid file types and display error', () => {
    // Intercept the file upload API call
    cy.intercept('POST', '/api/files/upload').as('uploadFile');

    // Attempt to upload an invalid file type (e.g., .txt)
    cy.get('[data-testid="pdf-file-input"]').selectFile('cypress/fixtures/sample.txt', { force: true });

    // Click upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for API call
    cy.wait('@uploadFile');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible').should('contain', 'Invalid file type. Only PDF is allowed');

    // Verify inline viewer is not visible
    cy.get('[data-testid="pdf-viewer-container"]').should('not.exist');

    // Verify file name is not displayed
    cy.get('[data-testid="uploaded-file-name"]').should('not.exist');

    // Verify file input is cleared
    cy.get('[data-testid="pdf-file-input"]').should('have.value', '');
  });
});
